function mapWidget(small=false,trip=null){const all=trucks().filter(v=>ui.mapFilter==='all'||ui.mapFilter===v.status);return `<div class="map-wrap" ${small?'style="height:335px"':''}><svg class="map" viewBox="0 0 1160 580" role="img" aria-label="${t('خريطة تخطيطية تجريبية للميناء والشاحنات','Schematic demo map of the port and trucks')}"><defs><pattern id="mapgrid" width="45" height="45" patternUnits="userSpaceOnUse"><path d="M45 0H0V45" fill="none" stroke="#dbe3ea" stroke-width="1"/></pattern></defs><rect width="1160" height="580" fill="#edf1f5"/><g transform="translate(${580*(1-ui.zoom)} ${290*(1-ui.zoom)}) scale(${ui.zoom})"><rect width="1160" height="580" fill="url(#mapgrid)"/><path d="M0 0h270l-25 65 54 65-26 57 51 32-17 70 33 56-70 87 39 41-36 107H0Z" fill="#c8e9ed"/><path d="M85 45h172M100 117h145M88 185h168M65 285h225" stroke="#b4dce1" stroke-width="8"/><g stroke="#fff" stroke-width="19" fill="none"><path d="M260 130 425 163 572 155 748 90 1080 120M290 280 455 295 580 245 775 280 1110 230M270 450 560 420 750 460 1090 420M390 0 420 160 455 290 410 580M710 0 735 220 700 400 740 580M970 0 950 210 1020 360 980 580"/></g><g stroke="#d7dfe8" stroke-width="2" fill="none"><path d="M260 130 425 163 572 155 748 90 1080 120M290 280 455 295 580 245 775 280 1110 230M270 450 560 420 750 460 1090 420M390 0 420 160 455 290 410 580M710 0 735 220 700 400 740 580M970 0 950 210 1020 360 980 580"/></g><g fill="#e0e5ed"><rect x="520" y="65" width="110" height="60" rx="8"/><rect x="830" y="330" width="98" height="70" rx="8"/><rect x="480" y="335" width="85" height="55" rx="8"/><rect x="1040" y="65" width="80" height="85" rx="8"/><rect x="800" y="495" width="115" height="50" rx="8"/></g><g fill="#d2e5d9"><rect x="840" y="60" width="80" height="58" rx="19"/><rect x="1030" y="485" width="88" height="65" rx="18"/></g><g fill="#d1dae3"><rect x="210" y="205" width="75" height="24" rx="3"/><rect x="210" y="236" width="75" height="24" rx="3"/><rect x="214" y="274" width="69" height="24" rx="3"/></g><g style="font-family:Josti,Arial" font-size="13" fill="#9da6b6"><text x="160" y="400" text-anchor="middle">${t('البحر','Sea')}</text><text x="615" y="112" text-anchor="middle">${t('المنطقة الصناعية','Industrial area')}</text><text x="881" y="370" text-anchor="middle">${t('مستودعات','Warehouses')}</text></g><circle cx="304" cy="256" r="23" fill="#2e1748"/><g transform="translate(292 244)" stroke="white" stroke-width="1.8" fill="none"><path d="M0 0h24v20H0ZM4 4h16M5 8v8M11 8v8M17 8v8"/></g>${trip?`<path d="M315 257 455 295 580 245 735 275 870 364" stroke="#32d5e7" stroke-width="7" stroke-linecap="round" stroke-dasharray="10 6" fill="none"/><circle cx="870" cy="364" r="12" fill="#2e1748"/><circle class="tracking-dot" id="tracking-dot" cx="670" cy="264" r="12" fill="#32d5e7" stroke="white" stroke-width="4"/>`:all.map(v=>{let x=verified()?v.x:Math.round(v.x/70)*70,y=verified()?v.y:Math.round(v.y/70)*70;return `<g class="truck-marker" tabindex="0" role="button" aria-label="${t('تفاصيل الشاحنة','Truck details')} ${v.id}" data-action="truck" data-id="${v.id}" transform="translate(${x} ${y})"><rect class="marker-box" x="-23" y="-21" width="46" height="42" rx="11" fill="white" stroke="#dde4eb"/><path d="M-13-9H4V6H-13ZM4-5h6l6 7v4H4" stroke="${colors[v.status]}" stroke-width="2" fill="none"/><circle cx="-7" cy="8" r="3" fill="${colors[v.status]}"/><circle cx="10" cy="8" r="3" fill="${colors[v.status]}"/><circle cx="18" cy="-16" r="5" fill="${colors[v.status]}" stroke="white" stroke-width="2"/></g>`}).join('')}</g></svg><div class="map-port-label"><b>${portName(trip?trip.port:ui.port)}</b><div class="tiny muted">${trip?t('محاكاة مسار الرحلة','Simulated trip route'):verified()?t('مواقع فعلية في العرض التجريبي','Precise demo positions'):t('مواقع تقريبية للزوار','Approximate positions for guests')}</div></div><div class="map-tools"><button class="round" data-action="zoom" data-id="in" aria-label="Zoom in">${I('plus')}</button><button class="round" data-action="zoom" data-id="out" aria-label="Zoom out">−</button><button class="round" data-action="zoom" data-id="reset" aria-label="Reset zoom">${I('pin')}</button></div><div class="map-caption">${t('خريطة تخطيطية دون اتصال · ليست للملاحة','Offline schematic map · Not for navigation')}</div></div>${!trip?`<div class="legend">${Object.entries(truckStatus).map(([k,v])=>`<span style="color:${colors[k]}"><i class="dot"></i>${nm(v)}</span>`).join('')}</div>`:''}`}